/**
 * Vocabulaire complémentaire : tous les mots de métier qui apparaissent dans les questions (missions, formation, quiz, séances) et qui
 * ne sont pas déjà dans les fiches du centre de formation. Chaque entrée : explication en mots simples + petit exemple chiffré.
 * Les alias s'écrivent comme on veut (accents et pluriels sont gérés : le dictionnaire les normalise).
 */
export interface BankTerm { term: string; aliases: string[]; simple: string; example?: string }
const T = (term: string, aliases: string, simple: string, example?: string): BankTerm => ({ term, aliases: aliases.split("|").map((a) => a.trim()).filter(Boolean), simple, example });

